// The page book-view: Book. It shows a book read through getBook and
// opens book-edit.

import {
  BOOK_VIEW_LOADED, BOOK_VIEW_FAILED,
} from "./events.js";
import { view } from "./view.js";

view({
  key: "book_id",
  source: { operation: "getBook", path: (parameters) => `/books/${encodeURIComponent(parameters.bookId)}` },
  // The fields hidden while their condition holds.
  hidden: {
    shelf_place: (record) => record.book_status === "retired",
  },
  actions: [
    {
      label: "Change",
      page: "book-edit",
      with: (record, parameters) => ({ bookId: record.book_id }),
    },
  ],
  messages: {
    failed: "This cannot be done right now. Try again in a moment.",
  },
  // What each operation's refusals say, by status: the page's failed states.
  refusals: {
    getBook: {
      "404": "There is no such book.",
    },
  },
  loaded: BOOK_VIEW_LOADED,
  failed: BOOK_VIEW_FAILED,
});
